12	import net.officefloor.hq.app.rollup.RollupService;
13	import net.officefloor.hq.app.sheet.SheetService;
14	import org.springframework.dao.DataIntegrityViolationException;
15	import org.springframework.orm.ObjectOptimisticLockingFailureException;
16	import org.springframework.http.HttpStatus;
17	import org.springframework.stereotype.Service;
18	import org.springframework.transaction.annotation.Transactional;
19	import org.springframework.web.server.ResponseStatusException;
20	
21	/**
22	 * The people on a sheet: listed in the order they were added, added and edited by name and grade. A
23	 * person's grade is dated: the first applies from the beginning of time, and each edit records the
24	 * grade from its from-date (the sheet's today when none is given), keeping those already recorded;
25	 * an edit leaving the grade in force on the sheet's today as it is, with no from-date, records none.
26	 * A
27	 * name is unique on the sheet, compared without regard to case (names arrive trimmed). A person can
28	 * be retired from a date (the sheet's today when none is given); they count as retired at once. A
29	 * person can be put on hold over a span of dates, and may have several holds over time. A person can name other people on the sheet as
30	 * their patrons, one at a time: not themselves, and not the same person twice. A user can watch a
31	 * person, and stop watching them; each user's watching is their own. A person may have their own
32	 * terms, in days; a claim's due-by takes them before the terms of the person's grade and the sheet's.
33	 * A person may have a contact (arriving trimmed and lower-cased, null for none), unique on the sheet.
34	 * A person may have aliases (arriving trimmed), sharing the names' uniqueness: an alias equals no name
35	 * or alias on the sheet, and no name equals an alias.
36	 * Nor may a name or alias be used on a sheet when another sheet of its tree (see
37	 * {@link SheetService#tree}) already uses it as a name or alias. People who already clash so are not
38	 * changed: they show as clashing, and every edit of them is refused until it renames them to a name
39	 * that does not clash and leaves them no clashing alias.
40	 */
41	@Service
42	public class PersonService {
43	
44	    private final PersonRepository people;
45	    private final SheetService sheets;
46	    private final Audit audit;
47	    private final RollupService rollup;
48	    private final PatronRepository patrons;
49	    private final RoleService roles;
50	    private final WatchRepository watches;
51	
52	    public PersonService(PersonRepository people, SheetService sheets, Audit audit, RollupService rollup,
53	            PatronRepository patrons, RoleService roles, WatchRepository watches) {
54	        this.roles = roles;
55	        this.watches = watches;
56	        this.people = people;
57	        this.patrons = patrons;
58	        this.sheets = sheets;
59	        this.audit = audit;
60	        this.rollup = rollup;
61	    }
62	
63	    @Transactional(readOnly = true)
64	    public List<Person> list(String sheetId) {
65	        return people.findBySheetIdOrderByIdAsc(sheetId);
66	    }
67	
68	    @Transactional
69	    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
70	        return add(sheetId, user, name, grade, terms, null);
71	    }
72	
73	    @Transactional
74	    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
75	        roles.refuseViewer(sheetId, user);
76	        sheets.load(sheetId, user);
77	        RollupService.Snapshot before = rollup.snapshot(sheetId);
78	        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, name) || people.existsAliasOnSheet(sheetId, name)
79	                || usedInTree(sheetId, name, null)) {
80	            throw nameInUse();
81	        }
82	        if (contact != null && people.existsBySheetIdAndContact(sheetId, contact)) {
83	            throw contactInUse();
84	        }
85	        Person person = new Person(sheetId, name, grade, sheets.today(sheetId));
86	        person.setTerms(terms);
87	        person.setContact(contact);
88	        Person added = save(person);
89	        audit.recordOnCommit(record("PERSON_ADDED", sheetId, user, added, sheets.today(sheetId))
90	                + (terms != null ? " terms=" + terms : "") + (contact != null ? " contact=" + contact : ""));
91	        rollup.recordChanges(sheetId, user, before);
92	        return added;
93	    }
94	
95	    @Transactional
96	    public Person update(String sheetId, String user, long id, long version, String name, String grade,
97	            LocalDate gradeFrom, Integer terms, String contact) {
98	        roles.refuseViewer(sheetId, user);
99	        RollupService.Snapshot before = rollup.snapshot(sheetId);
100	        Person person = people.findByIdAndSheetId(id, sheetId)
101	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
102	        if (person.getVersion() != version) {
103	            throw stale();
104	        }
105	        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, name, id) || people.existsAliasOnSheet(sheetId, name)
106	                || usedInTree(sheetId, name, null)) {
107	            throw nameInUse();
108	        }
109	        for (String alias : person.getAliases()) {
110	            if (usedInTree(sheetId, alias, null)) {
111	                throw new ResponseStatusException(HttpStatus.CONFLICT,
112	                        "The alias " + alias + " is already in use on a sheet of this sheet's tree.");
113	            }
114	        }
115	        if (contact != null && people.existsBySheetIdAndContactAndIdNot(sheetId, contact, id)) {
116	            throw contactInUse();
117	        }
118	        LocalDate today = sheets.today(sheetId);
119	        Integer termsBefore = person.getTerms();
120	        String contactBefore = person.getContact();
121	        person.setName(name);
122	        person.setTerms(terms);
123	        person.setContact(contact);
124	        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
125	            person.setGradeFrom(gradeFrom != null ? gradeFrom : today, grade, today);
126	        }
127	        Person saved = save(person);
128	        audit.recordOnCommit(record("PERSON_EDITED", sheetId, user, saved, today)
129	                + (Objects.equals(termsBefore, terms) ? "" : " terms=" + (terms != null ? terms : ""))
130	                + (Objects.equals(contactBefore, contact) ? "" : " contact=" + (contact != null ? contact : "")));
131	        rollup.recordChanges(sheetId, user, before);
132	        return saved;
133	    }
134	
135	    /**
136	     * Whether another sheet of the sheet's tree has a person, other than the one of {@code exceptId}
137	     * (null for none), with this name or alias, compared without regard to case.
138	     */
139	    @Transactional(readOnly = true)
140	    public boolean usedInTree(String sheetId, String name, Long exceptId) {
141	        Set<String> tree = sheets.tree(sheetId);
142	        return !tree.isEmpty() && people.existsNameOrAliasOnSheets(tree, name, exceptId != null ? exceptId : -1L);
143	    }
144	
145	    /**
146	     * The ids of those of the people on the sheet who clash: whose name or an alias another sheet of
147	     * its tree uses as a name or alias.
148	     */
149	    @Transactional(readOnly = true)
150	    public Set<Long> clashing(String sheetId, Collection<Person> those) {
151	        Set<String> tree = sheets.tree(sheetId);
152	        if (tree.isEmpty()) {
153	            return Set.of();
154	        }
155	        Set<String> used = new HashSet<>();
156	        for (Person other : people.findBySheetIdIn(tree)) {
157	            used.add(other.getName().toLowerCase(Locale.ROOT));
158	            other.getAliases().forEach(a -> used.add(a.toLowerCase(Locale.ROOT)));
159	        }
160	        Set<Long> clashing = new HashSet<>();
161	        for (Person person : those) {
162	            if (used.contains(person.getName().toLowerCase(Locale.ROOT))
163	                    || person.getAliases().stream().anyMatch(a -> used.contains(a.toLowerCase(Locale.ROOT)))) {
164	                clashing.add(person.getId());
165	            }
166	        }
167	        return clashing;
168	    }
169	
170	    /** Give the person an alias; refused (409) when it equals any name or alias on the sheet or its tree. */
171	    @Transactional
172	    public Person addAlias(String sheetId, String user, long id, String alias) {
173	        roles.refuseViewer(sheetId, user);
174	        Person person = people.lockByIdAndSheetId(id, sheetId)
175	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
176	        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, alias) || people.existsAliasOnSheet(sheetId, alias)
177	                || usedInTree(sheetId, alias, null)) {
178	            throw nameInUse();
179	        }
180	        person.addAlias(alias);
181	        Person saved = save(person);
182	        audit.recordOnCommit("PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
183	                + " alias=" + alias);
184	        return saved;
185	    }
186	
187	    /**
188	     * Give each of the people a grade from a from-date (the sheet's today when none is given), in list
189	     * order, exactly as editing each with the person form would (name, terms and contact kept). All or none: a
190	     * person not on the sheet refuses the lot. A viewer may grade no one: each person is refused and
191	     * none is graded.
192	     */
193	    @Transactional
194	    public List<Person> bulkGrade(String sheetId, String user, List<Long> ids, String grade, LocalDate gradeFrom) {
195	        try {
196	            roles.refuseViewer(sheetId, user);
197	        } catch (ResponseStatusException e) {
198	            if (e.getStatusCode() == HttpStatus.FORBIDDEN) {
199	                return List.of();
200	            }
201	            throw e;
202	        }
203	        Set<Long> wanted = new HashSet<>(ids);
204	        List<Person> chosen = people.findBySheetIdOrderByIdAsc(sheetId).stream()
205	                .filter(p -> wanted.contains(p.getId())).toList();
206	        if (chosen.size() != wanted.size()) {
207	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet.");
208	        }
209	        return chosen.stream().map(p -> update(sheetId, user, p.getId(), p.getVersion(), p.getName(), grade,
210	                gradeFrom, p.getTerms(), p.getContact())).toList();
211	    }
212	
213	    /**
214	     * Retire the person from a date, or from the sheet's today when none is given. Once the sheet's
215	     * today reaches that date their OPEN claims leave every live total, so the figures that move are recorded.
216	     */
217	    @Transactional
218	    public Person retire(String sheetId, String user, long id, LocalDate date) {
219	        roles.refuseViewer(sheetId, user);
220	        Person person = people.findByIdAndSheetId(id, sheetId)
221	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
222	        RollupService.Snapshot before = rollup.snapshot(sheetId);
223	        LocalDate from = date != null ? date : sheets.today(sheetId);
224	        person.setRetiredFrom(from, sheets.today(sheetId));
225	        Person saved = save(person);
226	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + saved.getName() + " from="
227	                + from);
228	        rollup.recordChanges(sheetId, user, before);
229	        return saved;
230	    }
231	
232	    /**
233	     * Put the person on hold from a date (the sheet's today when none is given) to an optional
234	     * to-date; refused (400) when the to-date is before the from-date. Their OPEN claims dated within
235	     * the hold leave every live total, so the figures that move are recorded.
236	     */
237	    @Transactional
238	    public Person hold(String sheetId, String user, long id, LocalDate fromDate, LocalDate toDate) {
239	        roles.refuseViewer(sheetId, user);
240	        RollupService.Snapshot before = rollup.snapshot(sheetId);
241	        Person person = people.lockByIdAndSheetId(id, sheetId)
242	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
243	        LocalDate from = fromDate != null ? fromDate : sheets.today(sheetId);
244	        if (toDate != null && toDate.isBefore(from)) {
245	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
246	        }
247	        person.addHold(from, toDate, sheets.today(sheetId));
248	        Person saved = save(person);
249	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName() + " from="
250	                + from);
251	        rollup.recordChanges(sheetId, user, before);
252	        return saved;
253	    }
254	
255	    @Transactional(readOnly = true)
256	    public List<Patron> patrons(String sheetId) {
257	        return patrons.findBySheetIdOrderByIdAsc(sheetId);
258	    }
259	
260	    /**
261	     * Name another person on the sheet as the person's patron; refused (409) when it is the person
262	     * themselves or already one of their patrons.
263	     */
264	    @Transactional
265	    public Patron addPatron(String sheetId, String user, long id, long patronId) {
266	        roles.refuseViewer(sheetId, user);
267	        Person person = people.findByIdAndSheetId(id, sheetId)
268	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
269	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
270	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron on this sheet."));
271	        if (person.getId().equals(patron.getId())) {
272	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be their own patron.");
273	        }
274	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
275	            throw patronTaken();
276	        }
277	        Patron added;
278	        try {
279	            added = patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
280	        } catch (DataIntegrityViolationException e) {
281	            throw patronTaken();
282	        }
283	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
284	                + " patron=" + patron.getName());
285	        return added;
286	    }
287	
288	    /** The ids of the people the user watches on the sheet. */
289	    @Transactional(readOnly = true)
290	    public List<Long> watched(String sheetId, String user) {
291	        return watches.findBySheetIdAndUserName(sheetId, user).stream().map(Watch::getPersonId).toList();
292	    }
293	
294	    /**
295	     * Start ({@code on}) or stop watching the person as the user; already so, nothing changes and
296	     * nothing is recorded.
297	     */
298	    @Transactional
299	    public void watch(String sheetId, String user, long id, boolean on) {
300	        roles.refuseViewer(sheetId, user);
301	        sheets.refuseIfArchived(sheetId);
302	        Person person = people.lockByIdAndSheetId(id, sheetId)
303	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
304	        var existing = watches.findByPersonIdAndUserName(person.getId(), user);
305	        if (on == existing.isPresent()) {
306	            return;
307	        }
308	        if (on) {
309	            watches.saveAndFlush(new Watch(sheetId, person.getId(), user));
310	        } else {
311	            watches.delete(existing.get());
312	            watches.flush();
313	        }
314	        audit.recordOnCommit((on ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + sheetId + " by=" + user
315	                + " name=" + person.getName());
316	    }
317	
318	    private static ResponseStatusException patronTaken() {
319	        return new ResponseStatusException(HttpStatus.CONFLICT, "That person is already a patron.");
320	    }
321	
322	    /** A person's record, with the grade in force on the sheet's today. */
323	    private static String record(String event, String sheetId, String user, Person person, LocalDate today) {
324	        return event + " sheet=" + sheetId + " by=" + user + " name=" + person.getName() + " grade="
325	                + person.gradeOn(today);
326	    }
327	
328	    /**
329	     * Save, refusing a name another user took on the sheet since it was checked, and an edit another
330	     * user saved over since the person was read.
331	     */
332	    private Person save(Person person) {
333	        try {
334	            return people.saveAndFlush(person);
335	        } catch (DataIntegrityViolationException e) {
336	            throw person.getContact() != null && String.valueOf(e.getMostSpecificCause().getMessage())
337	                    .toUpperCase().contains("PERSON_SHEET_CONTACT") ? contactInUse() : nameInUse();
338	        } catch (ObjectOptimisticLockingFailureException e) {
339	            throw stale();
340	        }
341	    }
342	
343	    /** The edit was made from a version of the person that another user has since saved over. */
344	    private static ResponseStatusException stale() {
345	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
346	                "Someone else has saved this person since it was opened.");
347	    }
348	
349	    private static ResponseStatusException contactInUse() {
350	        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on this sheet.");
351	    }
352	
353	    private static ResponseStatusException nameInUse() {
354	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet or its tree.");
355	    }
356	}
